def solve_nqueens(n, fixed, max_attempts=100):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or board[i] - i == col - row or board[i] + i == col + row:
                return False
        return True

    for attempt in range(max_attempts):
        board = [-1] * n
        valid = True
        for r, c in fixed.items():
            if not is_safe(board, r, c):
                valid = False
                break
            board[r] = c
        if not valid:
            continue
        rows_to_place = [r for r in range(n) if r not in fixed]
        random.shuffle(rows_to_place)
        success = True
        for row in rows_to_place:
            placed = False
            cols = list(range(n))
            random.shuffle(cols)
            for col in cols:
                if is_safe(board, row, col):
                    board[row] = col
                    placed = True
                    break
            if not placed:
                success = False
                break
        if success:
            return board
    return None

